//! Designer fork: JavaScript's way in to `editor::designer`.
//!
//! Written by hand rather than generated by `#[editor_commands]`: those commands return nothing (on desktop they
//! are serialized to another process), and a host needs answers. Web only.

use crate::EDITOR;
use crate::editor_wrapper::EditorWrapper;
use editor::application::Editor;
use editor::designer::{self, NewLayer};
use editor::messages::prelude::*;
use graph_craft::document::NodeId;
use wasm_bindgen::prelude::*;

/// Run something against the editor, if it is there and not in the middle of handling a message.
fn with_editor<T>(work: impl FnOnce(&mut Editor) -> T) -> Option<T> {
	EDITOR.with(|slot| {
		let mut guard = slot.try_lock();
		match guard.as_deref_mut() {
			Ok(Some(editor)) => Some(work(editor)),
			_ => None,
		}
	})
}

fn parse_id(id: &str) -> Option<NodeId> {
	id.parse::<u64>().ok().map(NodeId)
}

fn problem(message: impl std::fmt::Display) -> String {
	serde_json::json!({ "error": message.to_string() }).to_string()
}

#[wasm_bindgen]
impl EditorWrapper {
	/// Open a new document with one artboard of this size at the origin. `background` is `#rrggbb`, or empty for
	/// none. Returns the artboard's id.
	#[wasm_bindgen(js_name = designerNewDocument)]
	pub fn designer_new_document(&self, name: String, width: f64, height: f64, background: String) -> String {
		let artboard = NodeId::new();
		let background = (!background.is_empty()).then_some(background.as_str());
		for message in designer::new_document_messages(&name, artboard, width, height, background) {
			self.dispatch(message);
		}
		artboard.0.to_string()
	}

	/// Put a picture on the artboard above what is there. `layer` is JSON (`editor::designer::NewLayer`).
	/// Returns the new layer's id, or `{"error": ...}`.
	#[wasm_bindgen(js_name = designerAddLayer)]
	pub fn designer_add_layer(&self, artboard: String, layer: String, data: Vec<u8>) -> String {
		let Some(artboard) = parse_id(&artboard) else { return problem("that is not an artboard id") };
		let layer: NewLayer = match serde_json::from_str(&layer) {
			Ok(layer) => layer,
			Err(error) => return problem(format!("the layer could not be read: {error}")),
		};
		let id = NodeId::new();
		let Some(messages) = designer::add_layer_messages(id, artboard, &data, &layer) else {
			return problem("the bytes are not a picture");
		};
		for message in messages {
			self.dispatch(message);
		}
		with_editor(|editor| designer::label_new_layer(editor, id, &layer));
		id.0.to_string()
	}

	/// Once a design's layers are in: show all of it, with nothing selected.
	#[wasm_bindgen(js_name = designerShowAll)]
	pub fn designer_show_all(&self) {
		self.dispatch(DocumentMessage::DeselectAllLayers);
		self.dispatch(DocumentMessage::ZoomCanvasToFitAll);
	}

	/// What the active document holds, as JSON (`editor::designer::describe`).
	#[wasm_bindgen(js_name = designerDescribe)]
	pub fn designer_describe(&self) -> String {
		with_editor(|editor| designer::describe(editor).to_string()).unwrap_or_else(|| problem("the editor is busy"))
	}

	/// Start rendering one layer alone as `<name>.png`. Returns `{"bounds": [x0, y0, x1, y1]}` at once; the
	/// picture follows as an export of that name.
	#[wasm_bindgen(js_name = designerExportLayer)]
	pub fn designer_export_layer(&self, layer: String, scale: f64, name: String) -> String {
		let Some(layer) = parse_id(&layer) else { return problem("that is not a layer id") };
		match with_editor(|editor| designer::export_layer(editor, layer, scale, &name)) {
			Some(Ok(bounds)) => serde_json::json!({ "bounds": bounds }).to_string(),
			Some(Err(error)) => problem(error),
			None => problem("the editor is busy"),
		}
	}

	/// Ask for the active document's file; it follows the way a save does.
	#[wasm_bindgen(js_name = designerSaveDocument)]
	pub fn designer_save_document(&self) {
		self.dispatch(DocumentMessage::SaveDocument);
	}
}
